// 360~780,5nm间隔三刺激匹配权重系数表
struct clralgo_TristimulusWeightingFactors_5nm {
	struct clralgo_CIEXYZ xyz;         // 光源的白色所在坐标点
	float factors[85][3];   // 光源三刺激值权重系数
};

// 360~780,10nm间隔三刺激匹配权重系数表
struct clralgo_TristimulusWeightingFactors_10nm {
	struct clralgo_CIEXYZ xyz;         // 光源的三刺激值
	float factors[43][3];   // 光源三刺激值权重系数
};

// 获取CIE标准光源的三刺激值
// 参数：
// [in] observer:   要获取的三刺激值所在的观察者角度
// [in] illuminant: 要获取其三刺激值的标准光源
// 返回：标准光源illuminant的三刺激值
struct clralgo_CIEXYZ clralgo_get_white_point_of_illuminant(enum clralgo_StandardObserver observer,
	enum clralgo_StandardIlluminant illuminant);

#define clralgo_get_white_point_of_illuminant(observer, illuminant)    \
(TRISTIMULUS_WEIGHTING_WEIGHTING_FACTORS_10NM_TABLEs[observer][illuminant]->xyz)


